def kthPairSum(a, b, k):
    lo = a[0] + b[0]
    hi = a[-1] + b[-1]
    while lo < hi:
        mid = (lo + hi) // 2
        cnt = 0
        j = len(b) - 1
        for x in a:
            while j >= 0 and x + b[j] > mid:
                j -= 1
            if j < 0:
                break
            cnt += j + 1
        if cnt >= k:
            hi = mid
        else:
            lo = mid + 1
    return lo
